from __future__ import annotations

import pandas as pd

from ml_workbench.rules.eda import skew_hint
from ml_workbench.rules.modelling import small_data_hint


def test_hint_boosting_baseline_small_data() -> None:
    hint = small_data_hint(5_000)
    assert hint is not None
    assert "boosting" in hint.lower()

    assert small_data_hint(1_000_000) is None


def test_hint_log_transform_skewed_target() -> None:
    skewed = pd.Series([1.0, 1.1, 1.3, 1.6, 2.0, 5.0, 20.0, 100.0])
    hint = skew_hint(skewed)
    assert hint is not None
    assert "log transform is suggested" in hint
    assert "HINT-02" in hint

    symmetric = pd.Series([2.0, 3.0, 4.0, 5.0, 4.0, 3.0])
    assert skew_hint(symmetric) is None

    constant = pd.Series([7.0] * 10)
    assert skew_hint(constant) is None
